/**
 * O Livro Completo do Guerreiro (D&D 3.5, edição brasileira; scan sem camada de texto), cap. 2 "Classes de Prestígio".
 * Lido da imagem (Tabela 2-2 a 400dpi; texto a 250dpi); português, como no livro. Só dados. Livro 3.5.
 * Feito até aqui: Assassino do Oculto (pp. 16-17). O exemplo "Harlech" (PdM) fica de fora.
 * Classes de prestígio só valem do 2º nível em diante do personagem.
 */
export type CgPrestigeLevel = { level: number; bab: string; fort: number; ref: number; will: number; special: string; /** Dados de ataque furtivo (Tabela 2-5). */ sneakAttack?: string; /** Bônus de esquiva na CA montado (Tabela 2-4). */ acBonus?: number };

export type CgPrestigeClass = {
  id: string;
  name: string;
  page: number;
  hitDie: number;
  skillPointsPerLevel: string;
  requirements: { bab: string; skills: string[]; feats: string[]; other: string[] };
  classSkills: string[];
  levels: CgPrestigeLevel[];
  features: { name: string; text: string }[];
  /** Magias por dia 1º-4º círculos por nível de classe; null = "—"; 0 = só magias adicionais. */
  spellsPerDay?: (number | null)[][];
  /** Lista de magias da classe por círculo (1 a 4). */
  spellList?: Record<number, string[]>;
};

